import { Answers } from './types';

/**
 * Chuẩn hóa mã câu hỏi để so khớp.
 */
export const normalizeQuestionKey = (key: string | undefined): string => {
  if (!key) return '';
  return key.toLowerCase().replace(/[^a-z0-9]/g, '');
};

/**
 * Chuẩn hóa một chuỗi câu trả lời để so sánh.
 */
export const normalizeAnswer = (answer: string | undefined): string => {
  if (!answer) return '';
  const lower = answer.trim().toLowerCase();
  if (['đúng', 'd', 'true', 't'].includes(lower)) return 'đúng';
  if (['sai', 's', 'false', 'f'].includes(lower)) return 'sai';
  return lower.toUpperCase();
};

/**
 * Tính điểm tối đa dựa trên cấu hình số lượng câu hỏi.
 */
export const calculateMaxScore = (
    numMultipleChoice: number,
    numTrueFalse: number,
    numShortAnswer: number,
    numFreeResponse: number
): number => {
    // Trường hợp 1: Không có Tự luận (FR) và Trả lời ngắn (SA) -> Thang điểm 10
    if (numShortAnswer === 0 && numFreeResponse === 0) {
         if (numMultipleChoice > 0 || numTrueFalse > 0) return 10;
         return 0;
    }

    // Trường hợp 2: Có SA hoặc FR -> Tính theo điểm cố định tích lũy
    const mcPoints = numMultipleChoice * 0.25;
    const tfPoints = (numTrueFalse * 4) * 0.25; // Mỗi câu Đúng/Sai có 4 ý
    const saPoints = numShortAnswer * 0.25;
    const frPoints = numFreeResponse * 1.0;

    return mcPoints + tfPoints + saPoints + frPoints;
};

/**
 * Tính điểm thực tế dựa trên bài làm.
 */
export const calculateScore = (
    studentAnswers: Answers, 
    correctAnswers: Answers,
    numMultipleChoice: number,
    numTrueFalse: number,
    numShortAnswer: number = 0,
    numFreeResponse: number = 0
): number => {
    const isScaleTo10 = numShortAnswer === 0 && numFreeResponse === 0;

    let mcScore = 0;
    let tfScore = 0;
    let saScore = 0;

    // 1. Chấm Trắc nghiệm (MC)
    if (numMultipleChoice > 0) {
        let correctCount = 0;
        for (let i = 1; i <= numMultipleChoice; i++) {
            const key = `mc-${i}`;
            const normalizedKey = normalizeQuestionKey(key);
            if (studentAnswers[key] && correctAnswers[normalizedKey] !== undefined && normalizeAnswer(studentAnswers[key]) === normalizeAnswer(correctAnswers[normalizedKey])) {
                correctCount++;
            }
        }

        if (isScaleTo10) {
            // Nếu có cả Đúng/Sai thì MC chiếm 6 điểm, nếu không có TF thì MC chiếm 10 điểm
            const mcWeight = numTrueFalse > 0 ? 6 : 10;
            mcScore = (correctCount / numMultipleChoice) * mcWeight;
        } else {
            mcScore = correctCount * 0.25;
        }
    }

    // 2. Chấm Đúng/Sai (TF)
    const totalTfItems = numTrueFalse * 4;
    if (totalTfItems > 0) {
        let correctCount = 0;
        for (let i = 1; i <= numTrueFalse; i++) {
            ['a', 'b', 'c', 'd'].forEach(part => {
                const key = `tf-${i}-${part}`;
                const normalizedKey = normalizeQuestionKey(key);
                if (studentAnswers[key] && correctAnswers[normalizedKey] !== undefined && normalizeAnswer(studentAnswers[key]) === normalizeAnswer(correctAnswers[normalizedKey])) {
                    correctCount++;
                }
            });
        }

        if (isScaleTo10) {
            // Nếu có cả MC thì TF chiếm 4 điểm, nếu không có MC thì TF chiếm 10 điểm
            const tfWeight = numMultipleChoice > 0 ? 4 : 10;
            tfScore = (correctCount / totalTfItems) * tfWeight;
        } else {
            tfScore = correctCount * 0.25;
        }
    }

    // 3. Chấm Trả lời ngắn (SA)
    if (numShortAnswer > 0) {
        let correctCount = 0;
        for (let i = 1; i <= numShortAnswer; i++) {
            const key = `sa-${i}`;
            const normalizedKey = normalizeQuestionKey(key);
            if (studentAnswers[key] && correctAnswers[normalizedKey] !== undefined) {
                if (studentAnswers[key].trim().toLowerCase() === String(correctAnswers[normalizedKey]).trim().toLowerCase()) {
                    correctCount++;
                }
            }
        }
        // SA luôn dùng điểm cố định 0.25
        saScore = correctCount * 0.25;
    }

    return mcScore + tfScore + saScore;
};

import React, { useState } from 'react';
import { StudentResult, Answers } from '../types';
import { calculateScore, calculateMaxScore } from '../utils';

interface SubmissionSuccessViewProps {
    onRetakeTest: () => void;
    onExportResult: () => void;
    onReviewTest: () => void;
    onEndSession: () => void;
    result: StudentResult;
    correctAnswers: Answers;
    numMultipleChoice: number;
    numTrueFalse: number;
    numShortAnswer: number;
    numFreeResponse: number;
    teacherPassword?: string;
}

const SubmissionSuccessView: React.FC<SubmissionSuccessViewProps> = ({ 
    onRetakeTest, 
    onExportResult, 
    onReviewTest, 
    onEndSession,
    result, 
    correctAnswers, 
    numMultipleChoice, 
    numTrueFalse, 
    numShortAnswer,
    numFreeResponse, 
    teacherPassword 
}) => {
  const [isRetakeModalOpen, setIsRetakeModalOpen] = useState(false);
  const [retakePasswordInput, setRetakePasswordInput] = useState('');
  const [retakePasswordError, setRetakePasswordError] = useState('');

  const [isEndModalOpen, setIsEndModalOpen] = useState(false);
  const [endPasswordInput, setEndPasswordInput] = useState('');
  const [endPasswordError, setEndPasswordError] = useState('');

  const autoGradedMaxScore = calculateMaxScore(numMultipleChoice, numTrueFalse, numShortAnswer, numFreeResponse);
  const score = calculateScore(result.answers, correctAnswers, numMultipleChoice, numTrueFalse, numShortAnswer, numFreeResponse);

  const formatSubmissionTime = (isoString: string) => {
    if (!isoString) return '';
    const date = new Date(isoString);
    return date.toLocaleString('vi-VN', {
        hour: '2-digit', minute: '2-digit', second: '2-digit',
        day: '2-digit', month: '2-digit', year: 'numeric'
    });
  };

  const submissionMessage = () => {
    switch (result.submissionType) {
      case 'auto_visibility':
        return (
            <p className="mt-4 text-lg text-red-600 font-semibold bg-red-50 p-3 rounded-md border border-red-200">
                Bài làm đã được tự động nộp do thoát màn hình.
            </p>
        );
      case 'auto_timeout':
        return (
            <p className="mt-4 text-lg text-red-600 font-semibold bg-red-50 p-3 rounded-md border border-red-200">
                Bài làm đã được tự động nộp do hết thời gian.
            </p>
        );
      default:
        return null;
    }
  };

  const handleRetakeClick = () => {
    if (!teacherPassword) onRetakeTest();
    else setIsRetakeModalOpen(true);
  };

  const handleConfirmRetake = () => {
    if (teacherPassword && retakePasswordInput !== teacherPassword) {
      setRetakePasswordError('Mật khẩu không đúng.');
      return;
    }
    onRetakeTest();
  };

  const handleEndClick = () => setIsEndModalOpen(true);

  const handleConfirmEnd = () => {
    if (teacherPassword && endPasswordInput !== teacherPassword) {
        setEndPasswordError('Mật khẩu không đúng.');
        return;
    }
    onEndSession();
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100 p-4">
      {isRetakeModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-xl w-full max-w-sm">
            <h2 className="text-lg font-bold mb-4">Xác nhận Làm bài lại</h2>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700">Mật khẩu Giáo viên</label>
              <input type="password" value={retakePasswordInput} onChange={(e) => setRetakePasswordInput(e.target.value)} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md" />
              {retakePasswordError && <p className="text-xs text-red-500 mt-1">{retakePasswordError}</p>}
            </div>
            <div className="flex justify-end gap-3">
              <button onClick={() => setIsRetakeModalOpen(false)} className="px-4 py-2 bg-gray-200 rounded-md">Hủy</button>
              <button onClick={handleConfirmRetake} className="px-4 py-2 bg-green-600 text-white rounded-md">Đồng ý</button>
            </div>
          </div>
        </div>
      )}
      {isEndModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-xl w-full max-w-sm">
            <h2 className="text-lg font-bold mb-4">Kết thúc phiên</h2>
            {teacherPassword && (
              <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700">Mật khẩu Giáo viên</label>
                  <input type="password" value={endPasswordInput} onChange={(e) => setEndPasswordInput(e.target.value)} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md" />
                  {endPasswordError && <p className="text-xs text-red-500 mt-1">{endPasswordError}</p>}
              </div>
            )}
            <div className="flex justify-end gap-3">
              <button onClick={() => setIsEndModalOpen(false)} className="px-4 py-2 bg-gray-200 rounded-md">Hủy</button>
              <button onClick={handleConfirmEnd} className="px-4 py-2 bg-red-600 text-white rounded-md">Xác nhận</button>
            </div>
          </div>
        </div>
      )}
      <div className="text-center p-12 bg-white rounded-2xl shadow-lg max-w-lg w-full">
        <h1 className="text-4xl font-bold text-green-600 mb-4">Nộp bài thành công!</h1>
        {submissionMessage()}
        <p className="mt-4 text-lg text-gray-800">
          Học sinh: <span className="text-blue-700 font-bold">{result.name}</span>
        </p>
        <div className="mt-6 p-6 bg-gray-50 rounded-lg border border-gray-200">
            <h2 className="text-2xl font-bold text-indigo-700">Kết quả</h2>
            <div className="mt-4 text-3xl font-bold text-blue-600">
                {score.toFixed(2)} / {autoGradedMaxScore.toFixed(1)}
            </div>
            {(numFreeResponse > 0) && (
                <p className="mt-2 text-sm text-gray-500 italic">
                    (Điểm trên chưa bao gồm {numFreeResponse} câu Tự luận)
                </p>
            )}
        </div>
        <div className="mt-8 grid grid-cols-2 gap-4">
            <button onClick={handleRetakeClick} className="px-4 py-3 bg-green-600 text-white rounded-lg">Làm lại</button>
            <button onClick={onReviewTest} className="px-4 py-3 bg-yellow-500 text-white rounded-lg">Xem lại</button>
            <button onClick={onExportResult} className="px-4 py-3 bg-blue-600 text-white rounded-lg">Xuất PDF</button>
            <button onClick={handleEndClick} className="px-4 py-3 bg-red-600 text-white rounded-lg">Kết thúc</button>
        </div>
      </div>
    </div>
  );
};

export default SubmissionSuccessView;
